"""Auto-generated by ORIGIN (graphbench domain). Self-contained experiment.

Design spec: see spec.json alongside this file. Versioned and kept forever.

Emits result schema v2 with BOTH wall-clock timing and a machine-independent
operation count (edge relaxations), plus input/output digests, so a replay can
verify the answer, not merely its speed.
"""
import hashlib, json, platform, statistics, sys, time

CONFIG = {
    "kind": "benchmark",
    "round": 2,
    "algorithms": [
        "dijkstra_heap",
        "dijkstra_array",
        "bellman_ford",
        "spfa",
        "bfs_unit"
    ],
    "regimes": [
        "sparse_random",
        "dense_random",
        "grid_2d",
        "unit_weight"
    ],
    "sizes": [
        512
    ],
    "trials": 5,
    "seed": 5242,
    "timeout_s": 600,
    "hypothesis_ids": [
        "hyp_dfa38e8bf8"
    ],
    "origin_version": "1.5.0"
}
RESULT_SCHEMA_VERSION = 2

def gen_sparse_random(n, seed):
    import random
    rnd = random.Random(seed)
    adj = [[] for _ in range(n)]
    for u in range(1, n):                     # spanning tree keeps it connected
        v = rnd.randrange(u)
        w = rnd.randint(1, 20)
        adj[u].append((v, w))
        adj[v].append((u, w))
    for _ in range(2 * n):
        u, v = rnd.randrange(n), rnd.randrange(n)
        if u != v:
            w = rnd.randint(1, 20)
            adj[u].append((v, w))
            adj[v].append((u, w))
    return adj


def gen_dense_random(n, seed):
    import random
    rnd = random.Random(seed)
    adj = [[] for _ in range(n)]
    target = max(1, (n * n) // 8)
    for u in range(1, n):
        v = rnd.randrange(u)
        w = rnd.randint(1, 20)
        adj[u].append((v, w))
        adj[v].append((u, w))
    for _ in range(target):
        u, v = rnd.randrange(n), rnd.randrange(n)
        if u != v:
            w = rnd.randint(1, 20)
            adj[u].append((v, w))
            adj[v].append((u, w))
    return adj


def gen_grid_2d(n, seed):
    """A square lattice. The graph has side^2 vertices, which is the largest
    square <= n — padding up to n would leave isolated vertices with infinite
    distance, and an unreachable vertex is a broken benchmark, not a topology.
    """
    import math
    import random
    rnd = random.Random(seed)
    side = max(2, int(math.isqrt(n)))
    total = side * side
    adj = [[] for _ in range(total)]
    for r in range(side):
        for c in range(side):
            i = r * side + c
            if c + 1 < side:
                w = rnd.randint(1, 9)
                adj[i].append((i + 1, w))
                adj[i + 1].append((i, w))
            if r + 1 < side:
                w = rnd.randint(1, 9)
                adj[i].append((i + side, w))
                adj[i + side].append((i, w))
    return adj


def gen_unit_weight(n, seed):
    """Sparse graph with every weight 1 — the precondition for bfs_unit."""
    import random
    rnd = random.Random(seed)
    adj = [[] for _ in range(n)]
    for u in range(1, n):
        v = rnd.randrange(u)
        adj[u].append((v, 1))
        adj[v].append((u, 1))
    for _ in range(2 * n):
        u, v = rnd.randrange(n), rnd.randrange(n)
        if u != v:
            adj[u].append((v, 1))
            adj[v].append((u, 1))
    return adj


def dijkstra_heap(n, adj, src):
    import heapq
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    relax = 0
    pq = [(0, src)]
    seen = [False] * n
    while pq:
        d, u = heapq.heappop(pq)
        if seen[u]:
            continue
        seen[u] = True
        for v, w in adj[u]:
            relax += 1
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist, relax


def dijkstra_array(n, adj, src):
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    relax = 0
    done = [False] * n
    for _ in range(n):
        best, bd = -1, INF
        for i in range(n):
            if not done[i] and dist[i] < bd:
                best, bd = i, dist[i]
        if best < 0:
            break
        done[best] = True
        for v, w in adj[best]:
            relax += 1
            nd = bd + w
            if nd < dist[v]:
                dist[v] = nd
    return dist, relax


def bellman_ford(n, adj, src):
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    relax = 0
    for _ in range(n - 1):
        changed = False
        for u in range(n):
            du = dist[u]
            if du == INF:
                continue
            for v, w in adj[u]:
                relax += 1
                if du + w < dist[v]:
                    dist[v] = du + w
                    changed = True
        if not changed:
            break
    return dist, relax


def spfa(n, adj, src):
    from collections import deque
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    relax = 0
    inq = [False] * n
    q = deque([src])
    inq[src] = True
    while q:
        u = q.popleft()
        inq[u] = False
        du = dist[u]
        for v, w in adj[u]:
            relax += 1
            if du + w < dist[v]:
                dist[v] = du + w
                if not inq[v]:
                    inq[v] = True
                    q.append(v)
    return dist, relax


def bfs_unit(n, adj, src):
    """Breadth-first search. CORRECT ONLY when every edge weight is 1.

    Deliberately included: it is dramatically faster where it applies and
    silently wrong elsewhere, so the domain contains a real correctness
    boundary for the critic to find.
    """
    from collections import deque
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    relax = 0
    q = deque([src])
    while q:
        u = q.popleft()
        du = dist[u]
        for v, w in adj[u]:
            relax += 1
            if dist[v] == INF:
                dist[v] = du + 1
                q.append(v)
    return dist, relax


ALGORITHMS = {"dijkstra_heap": dijkstra_heap, "dijkstra_array": dijkstra_array, "bellman_ford": bellman_ford, "spfa": spfa, "bfs_unit": bfs_unit}
GENERATORS = {"sparse_random": gen_sparse_random, "dense_random": gen_dense_random, "grid_2d": gen_grid_2d, "unit_weight": gen_unit_weight}


def digest(obj):
    h = hashlib.sha256()
    h.update(repr(obj).encode())
    return h.hexdigest()[:16]


def file_digest(path):
    try:
        return hashlib.sha256(open(path, "rb").read()).hexdigest()[:16]
    except OSError:
        return ""


def reference(n, adj, src):
    """Trusted baseline used ONLY to check correctness, never timed."""
    import heapq
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    pq = [(0, src)]
    seen = [False] * n
    while pq:
        d, u = heapq.heappop(pq)
        if seen[u]:
            continue
        seen[u] = True
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (d + w, v))
    return dist


def reference_workload():
    import random
    rnd = random.Random(987654321)
    data = [rnd.random() for _ in range(20000)]
    times = []
    for _ in range(5):
        copy = list(data)
        t0 = time.perf_counter()
        copy.sort()
        times.append(time.perf_counter() - t0)
    return statistics.median(times)


def environment():
    import os
    return {
        "python_version": platform.python_version(),
        "python_implementation": platform.python_implementation(),
        "system": platform.system(), "release": platform.release(),
        "machine": platform.machine(), "processor": platform.processor(),
        "cpu_count": os.cpu_count(),
        "origin_version": CONFIG.get("origin_version", "unknown"),
        "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "timer": "time.perf_counter",
        "timer_resolution_s": time.get_clock_info("perf_counter").resolution,
    }


def main():
    rows = []
    for alg_name in CONFIG["algorithms"]:
        fn = ALGORITHMS[alg_name]
        for regime in CONFIG["regimes"]:
            gen = GENERATORS[regime]
            for n in CONFIG["sizes"]:
                times, relax_counts = [], []
                correct = True
                in_dig = out_dig = ""
                for t in range(CONFIG["trials"]):
                    adj = gen(n, CONFIG["seed"] + t)
                    size = len(adj)
                    expected = reference(size, adj, 0)
                    if t == 0:
                        in_dig = digest([sorted(e) for e in adj])
                    t0 = time.perf_counter()
                    dist, relax = fn(size, adj, 0)
                    dt = time.perf_counter() - t0
                    if list(dist) != expected:
                        correct = False       # recorded, NOT crashed: a wrong
                        # answer is a research result about this candidate's
                        # preconditions, and the run must report it honestly.
                    if t == 0:
                        out_dig = digest(list(dist))
                    times.append(dt)
                    relax_counts.append(relax)
                stdev = statistics.stdev(times) if len(times) > 1 else 0.0
                rows.append({
                    "algorithm": alg_name, "regime": regime, "n": n,
                    "correct": correct, "trials": CONFIG["trials"],
                    "samples": times,
                    "mean_s": statistics.fmean(times),
                    "median_s": statistics.median(times),
                    "stdev_s": stdev,
                    "sem_s": stdev / (len(times) ** 0.5) if len(times) > 1 else 0.0,
                    "min_s": min(times),
                    "relaxations": int(statistics.median(relax_counts)),
                    "input_digest": in_dig, "output_digest": out_dig,
                })
    payload = {
        "schema_version": RESULT_SCHEMA_VERSION,
        "environment": environment(), "config": CONFIG,
        "code_digest": file_digest(__file__),
        "reference_workload_s": reference_workload(),
        "rows": rows,
    }
    with open("result.json", "w") as f:
        json.dump(payload, f, indent=2)
    print("OK", len(rows), "measurements")


main()
